using namespace std;

int main() {
    int q;
    if (scanf("%d", &q) != 1) return 0;
    vector<array<long long, 3>> ops(q);
    vector<long long> coords;
    for (auto &op : ops) {
        scanf("%lld %lld", &op[0], &op[1]);
        if (op[0] == 1) coords.push_back(op[1]);
        else scanf("%lld", &op[2]);
    }
    sort(coords.begin(), coords.end());
    int m = coords.size();
    vector<int> bit(m + 1, 0);
    auto prefix = [&](int i) {
        int total = 0;
        for (; i; i -= i & -i) total += bit[i];
        return total;
    };
    string result;
    for (auto &op : ops) {
        if (op[0] == 1) {
            int i = lower_bound(coords.begin(), coords.end(), op[1]) - coords.begin() + 1;
            for (; i <= m; i += i & -i) bit[i]++;
        } else {
            // Placed obstacles in [x, x+size): indices [lower_bound(x), lower_bound(x+size)).
            int left = lower_bound(coords.begin(), coords.end(), op[1]) - coords.begin();
            int right = lower_bound(coords.begin(), coords.end(), op[1] + op[2]) - coords.begin();
            result += prefix(right) == prefix(left) ? '1' : '0';
