import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static int lowerBound(long[] a, int len, long key) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < key) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int q = nextInt();
        int[] type = new int[q];
        long[] xs = new long[q], sizes = new long[q], coords = new long[q];
        int m = 0;
        for (int i = 0; i < q; i++) {
            type[i] = nextInt();
            xs[i] = nextLong();
            if (type[i] == 1) coords[m++] = xs[i];
            else sizes[i] = nextLong();
        }
        Arrays.sort(coords, 0, m);
        int[] bit = new int[m + 1];
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < q; t++) {
            if (type[t] == 1) {
                for (int i = lowerBound(coords, m, xs[t]) + 1; i <= m; i += i & -i) bit[i]++;
            } else {
                // Placed obstacles in [x, x+size): indices [lower_bound(x), lower_bound(x+size)).
                int left = lowerBound(coords, m, xs[t]), right = lowerBound(coords, m, xs[t] + sizes[t]);
                int count = 0;
                for (int i = right; i > 0; i -= i & -i) count += bit[i];
                for (int i = left; i > 0; i -= i & -i) count -= bit[i];
                sb.append(count == 0 ? '1' : '0');
            }
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	q := int(nextInt())
	typ := make([]int64, q)
	xs := make([]int64, q)
	sizes := make([]int64, q)
	coords := []int64{}
	for i := 0; i < q; i++ {
		typ[i], xs[i] = nextInt(), nextInt()
		if typ[i] == 1 {
			coords = append(coords, xs[i])
		} else {
			sizes[i] = nextInt()
		}
	}
	sort.Slice(coords, func(i, j int) bool { return coords[i] < coords[j] })
	m := len(coords)
	lowerBound := func(key int64) int {
		return sort.Search(m, func(i int) bool { return coords[i] >= key })
	}
	bit := make([]int, m+1)
	prefix := func(i int) int {
		total := 0
		for ; i > 0; i -= i & -i {
			total += bit[i]
		}
		return total
	}
	out := make([]byte, 0, q+1)
	for t := 0; t < q; t++ {
		if typ[t] == 1 {
			for i := lowerBound(xs[t]) + 1; i <= m; i += i & -i {
				bit[i]++
			}
		} else {
			// Placed obstacles in [x, x+size): indices [lower_bound(x), lower_bound(x+size)).
			if prefix(lowerBound(xs[t]+sizes[t])) == prefix(lowerBound(xs[t])) {
				out = append(out, '1')
			} else {
				out = append(out, '0')
			}
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
